package com.librarypilot;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class LibraryPilotPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(LibraryPilotPlugin.class);
		RuneLite.main(args);
	}
}

package com.librarypilot;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class PathFinderTest
{
	private static final int BX = CollisionGrid.BASE_X;
	private static final int BY = CollisionGrid.BASE_Y;

	private static WorldPoint wp(int x, int y, int plane)
	{
		return new WorldPoint(BX + x, BY + y, plane);
	}

	private static int[][][] open()
	{
		return new int[CollisionGrid.PLANES][CollisionGrid.SIZE][CollisionGrid.SIZE];
	}

	@Test
	public void walksStraightLine()
	{
		CollisionGrid grid = new CollisionGrid(open());
		List<PathFinder.Step> steps = PathFinder.find(grid, wp(10, 10, 0), Collections.singletonList(wp(15, 10, 0)), Collections.emptyList());
		assertEquals(6, steps.size());
		for (PathFinder.Step s : steps)
		{
			assertEquals(BY + 10, s.getPoint().getY());
		}
	}

	@Test
	public void goesAroundWall()
	{
		int[][][] flags = open();
		// A wall along the east side of x=12 for y 5..15, open at both ends
		for (int y = 5; y <= 15; y++)
		{
			flags[0][12][y] |= CollisionDataFlag.BLOCK_MOVEMENT_EAST;
			flags[0][13][y] |= CollisionDataFlag.BLOCK_MOVEMENT_WEST;
		}
		CollisionGrid grid = new CollisionGrid(flags);
		List<PathFinder.Step> steps = PathFinder.find(grid, wp(10, 10, 0), Collections.singletonList(wp(15, 10, 0)), Collections.emptyList());
		assertTrue(steps.size() > 6);
		assertTrue(steps.stream().anyMatch(s -> s.getPoint().getY() >= BY + 16 || s.getPoint().getY() <= BY + 4));
	}

	@Test
	public void prefersFasterTransport()
	{
		CollisionGrid grid = new CollisionGrid(open());
		Transport stairs = new Transport(wp(40, 10, 1), null, "Climb-down", Collections.singletonList(wp(40, 10, 1)), wp(40, 11, 0), 40, false);
		Transport railing = new Transport(wp(12, 10, 1), null, "Jump-down", Collections.singletonList(wp(12, 10, 1)), wp(13, 10, 0), 50, false);
		List<PathFinder.Step> steps = PathFinder.find(grid, wp(10, 10, 1), Collections.singletonList(wp(10, 10, 0)),
			Arrays.asList(stairs, railing));
		assertSame(railing, steps.stream().filter(s -> s.getVia() != null).findFirst().get().getVia());
		assertEquals(wp(10, 10, 0), steps.get(steps.size() - 1).getPoint());
	}

	@Test
	public void unreachableGivesEmptyPath()
	{
		CollisionGrid grid = new CollisionGrid(open());
		List<PathFinder.Step> steps = PathFinder.find(grid, wp(10, 10, 2), Collections.singletonList(wp(10, 10, 0)), Collections.emptyList());
		assertTrue(steps.isEmpty());
	}
}

package com.librarypilot;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

/**
 * Uses the real object positions of the library's south-west and top-floor staircases, taken from the game cache.
 */
public class TransportScannerTest
{
	private static int[][][] grid;

	private static TransportScanner.Found found(int x0, int y0, int x1, int y1, int plane, int direction)
	{
		for (int x = x0; x <= x1; x++)
		{
			for (int y = y0; y <= y1; y++)
			{
				grid[plane][x - CollisionGrid.BASE_X][y - CollisionGrid.BASE_Y] = CollisionDataFlag.BLOCK_MOVEMENT_OBJECT;
			}
		}
		return new TransportScanner.Found(null, "Climb", new WorldPoint(x0, y0, plane), new WorldPoint(x1, y1, plane), false, direction);
	}

	@Test
	public void groundFloorStairsBoardEastLandWest()
	{
		grid = new int[CollisionGrid.PLANES][CollisionGrid.SIZE][CollisionGrid.SIZE];
		TransportScanner.Found up1 = found(1614, 3794, 1616, 3795, 0, 1);
		TransportScanner.Found up2 = found(1614, 3796, 1616, 3797, 0, 1);
		TransportScanner.Found down1 = found(1611, 3794, 1614, 3795, 1, -1);
		TransportScanner.Found down2 = found(1611, 3796, 1614, 3797, 1, -1);
		List<TransportScanner.Found> all = Arrays.asList(up1, up2, down1, down2);
		CollisionGrid g = new CollisionGrid(grid);

		Transport up = TransportScanner.stairs(g, Collections.emptyMap(), all, up1);
		assertEquals(1, up.getDestination().getPlane());
		assertEquals(1610, up.getDestination().getX());
		assertTrue(up.getOrigins().stream().allMatch(o -> o.getX() == 1617));

		Transport down = TransportScanner.stairs(g, Collections.emptyMap(), all, down1);
		assertEquals(0, down.getDestination().getPlane());
		assertEquals(1617, down.getDestination().getX());
		assertTrue(down.getOrigins().stream().allMatch(o -> o.getX() == 1610));
	}

	@Test
	public void middleFloorStairsBoardSouthLandNorth()
	{
		grid = new int[CollisionGrid.PLANES][CollisionGrid.SIZE][CollisionGrid.SIZE];
		TransportScanner.Found up = found(1621, 3792, 1622, 3794, 1, 1);
		TransportScanner.Found down = found(1621, 3794, 1622, 3797, 2, -1);
		List<TransportScanner.Found> all = Arrays.asList(up, down);
		CollisionGrid g = new CollisionGrid(grid);

		Transport t = TransportScanner.stairs(g, Collections.emptyMap(), all, up);
		assertEquals(new WorldPoint(1621, 3798, 2).getY(), t.getDestination().getY());
		assertTrue(t.getOrigins().stream().allMatch(o -> o.getY() == 3791));

		Transport back = TransportScanner.stairs(g, Collections.emptyMap(), all, down);
		assertEquals(3791, back.getDestination().getY());
		assertEquals(1, back.getDestination().getPlane());
		assertTrue(back.getOrigins().stream().allMatch(o -> o.getY() == 3798));
	}

	@Test
	public void learnedLandingWins()
	{
		grid = new int[CollisionGrid.PLANES][CollisionGrid.SIZE][CollisionGrid.SIZE];
		TransportScanner.Found up = found(1621, 3792, 1622, 3794, 1, 1);
		TransportScanner.Found down = found(1621, 3794, 1622, 3797, 2, -1);
		WorldPoint real = new WorldPoint(1622, 3799, 2);
		Transport t = TransportScanner.stairs(new CollisionGrid(grid),
			Collections.singletonMap(Transport.key(up.sw, 2), real), Arrays.asList(up, down), up);
		assertEquals(real, t.getDestination());
		assertTrue(t.isLearned());
	}
}

package com.librarypilot;

import net.runelite.api.CollisionData;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;

/**
 * Snapshot of the collision flags for the library region (64x64 tiles, floors 0-2).
 */
class CollisionGrid
{
	static final int BASE_X = 1600;
	static final int BASE_Y = 3776;
	static final int SIZE = 64;
	static final int PLANES = 3;

	private static final int FULL = CollisionDataFlag.BLOCK_MOVEMENT_FULL;
	private static final int N = CollisionDataFlag.BLOCK_MOVEMENT_NORTH;
	private static final int S = CollisionDataFlag.BLOCK_MOVEMENT_SOUTH;
	private static final int E = CollisionDataFlag.BLOCK_MOVEMENT_EAST;
	private static final int W = CollisionDataFlag.BLOCK_MOVEMENT_WEST;
	private static final int NE = CollisionDataFlag.BLOCK_MOVEMENT_NORTH_EAST;
	private static final int NW = CollisionDataFlag.BLOCK_MOVEMENT_NORTH_WEST;
	private static final int SE = CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_EAST;
	private static final int SW = CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_WEST;

	/**
	 * [plane][x][y], region-local. Tiles outside the loaded scene are fully blocked.
	 */
	private final int[][][] flags;

	CollisionGrid(int[][][] flags)
	{
		this.flags = flags;
	}

	static CollisionGrid fromWorldView(WorldView wv)
	{
		CollisionData[] maps = wv.getCollisionMaps();
		int[][][] flags = new int[PLANES][SIZE][SIZE];
		for (int p = 0; p < PLANES; p++)
		{
			int[][] sceneFlags = maps == null || maps[p] == null ? null : maps[p].getFlags();
			for (int x = 0; x < SIZE; x++)
			{
				for (int y = 0; y < SIZE; y++)
				{
					int sx = BASE_X + x - wv.getBaseX();
					int sy = BASE_Y + y - wv.getBaseY();
					if (sceneFlags == null || sx < 0 || sy < 0 || sx >= sceneFlags.length || sy >= sceneFlags[sx].length)
					{
						flags[p][x][y] = FULL;
					}
					else
					{
						flags[p][x][y] = sceneFlags[sx][sy];
					}
				}
			}
		}
		return new CollisionGrid(flags);
	}

	static boolean inRegion(WorldPoint wp)
	{
		int x = wp.getX() - BASE_X;
		int y = wp.getY() - BASE_Y;
		return x >= 0 && y >= 0 && x < SIZE && y < SIZE && wp.getPlane() >= 0 && wp.getPlane() < PLANES;
	}

	static int node(WorldPoint wp)
	{
		return node(wp.getPlane(), wp.getX() - BASE_X, wp.getY() - BASE_Y);
	}

	static int node(int plane, int x, int y)
	{
		return (plane * SIZE + x) * SIZE + y;
	}

	static WorldPoint point(int node)
	{
		int y = node % SIZE;
		int x = (node / SIZE) % SIZE;
		int plane = node / (SIZE * SIZE);
		return new WorldPoint(BASE_X + x, BASE_Y + y, plane);
	}

	static int nodeCount()
	{
		return PLANES * SIZE * SIZE;
	}

	private boolean blocked(int p, int x, int y, int mask)
	{
		if (x < 0 || y < 0 || x >= SIZE || y >= SIZE)
		{
			return true;
		}
		return (flags[p][x][y] & mask) != 0;
	}

	boolean walkable(WorldPoint wp)
	{
		return inRegion(wp) && !blocked(wp.getPlane(), wp.getX() - BASE_X, wp.getY() - BASE_Y, FULL);
	}

	/**
	 * Whether a player can step from region-local (x, y) by (dx, dy), using the same rules as the game's pathfinder.
	 */
	boolean canMove(int p, int x, int y, int dx, int dy)
	{
		int tx = x + dx;
		int ty = y + dy;
		if (dx == 0 && dy == 1)
		{
			return !blocked(p, tx, ty, S | FULL);
		}
		if (dx == 0 && dy == -1)
		{
			return !blocked(p, tx, ty, N | FULL);
		}
		if (dx == 1 && dy == 0)
		{
			return !blocked(p, tx, ty, W | FULL);
		}
		if (dx == -1 && dy == 0)
		{
			return !blocked(p, tx, ty, E | FULL);
		}
		if (dx == 1 && dy == 1)
		{
			return !blocked(p, tx, ty, SW | S | W | FULL) && !blocked(p, tx, y, W | FULL) && !blocked(p, x, ty, S | FULL);
		}
		if (dx == -1 && dy == 1)
		{
			return !blocked(p, tx, ty, SE | S | E | FULL) && !blocked(p, tx, y, E | FULL) && !blocked(p, x, ty, S | FULL);
		}
		if (dx == 1 && dy == -1)
		{
			return !blocked(p, tx, ty, NW | N | W | FULL) && !blocked(p, tx, y, W | FULL) && !blocked(p, x, ty, N | FULL);
		}
		if (dx == -1 && dy == -1)
		{
			return !blocked(p, tx, ty, NE | N | E | FULL) && !blocked(p, tx, y, E | FULL) && !blocked(p, x, ty, N | FULL);
		}
		return false;
	}

	/**
	 * Whether there is a wall between a tile and its cardinal neighbour. Ignores whether either tile is occupied,
	 * which is what matters when interacting with a solid object such as a bookshelf or an NPC.
	 */
	boolean wallBetween(WorldPoint from, WorldPoint to)
	{
		int p = from.getPlane();
		int x = from.getX() - BASE_X;
		int y = from.getY() - BASE_Y;
		int dx = to.getX() - from.getX();
		int dy = to.getY() - from.getY();
		int tx = x + dx;
		int ty = y + dy;
		if (dx == 0 && dy == 1)
		{
			return blocked(p, x, y, N) || blocked(p, tx, ty, S);
		}
		if (dx == 0 && dy == -1)
		{
			return blocked(p, x, y, S) || blocked(p, tx, ty, N);
		}
		if (dx == 1 && dy == 0)
		{
			return blocked(p, x, y, E) || blocked(p, tx, ty, W);
		}
		if (dx == -1 && dy == 0)
		{
			return blocked(p, x, y, W) || blocked(p, tx, ty, E);
		}
		return true;
	}
}

package com.librarypilot;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.Path2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

class LibraryPilotOverlay extends Overlay
{
	private final Client client;
	private final LibraryPilotPlugin plugin;
	private final LibraryPilotConfig config;

	@Inject
	LibraryPilotOverlay(Client client, LibraryPilotPlugin plugin, LibraryPilotConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(OverlayPriority.HIGH);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		List<PathFinder.Step> steps = plugin.getPath();
		if (steps.isEmpty())
		{
			return null;
		}

		WorldView wv = client.getTopLevelWorldView();
		int plane = wv.getPlane();
		Color color = config.pathColor();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setStroke(new BasicStroke(config.lineWidth(), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));

		// Draw the part of the path on this floor, up to the first staircase or railing
		Path2D.Double line = new Path2D.Double();
		boolean started = false;
		TileObject transportObject = null;
		for (PathFinder.Step step : steps)
		{
			if (step.getVia() != null)
			{
				transportObject = step.getVia().getObject();
				break;
			}
			if (step.getPoint().getPlane() != plane)
			{
				break;
			}
			Point p = toCanvas(wv, step.getPoint());
			if (p == null)
			{
				continue;
			}
			if (started)
			{
				line.lineTo(p.getX(), p.getY());
			}
			else
			{
				line.moveTo(p.getX(), p.getY());
				started = true;
			}
		}

		Shape highlight = null;
		Point end = null;
		if (transportObject != null)
		{
			if (transportObject.getPlane() == plane)
			{
				highlight = transportObject.getClickbox();
				end = toCanvas(wv, transportObject.getLocalLocation());
			}
		}
		else
		{
			NPC npc = plugin.getTargetNpc();
			WorldPoint tile = plugin.getTargetTile();
			if (npc != null && npc.getWorldLocation().getPlane() == plane)
			{
				highlight = npc.getConvexHull();
				end = toCanvas(wv, npc.getLocalLocation());
			}
			else if (plugin.getTargetObject() != null && plugin.getTargetObject().getPlane() == plane)
			{
				TileObject shelf = plugin.getTargetObject();
				highlight = shelf.getClickbox();
				end = toCanvas(wv, shelf.getLocalLocation());
			}
			else if (tile != null && tile.getPlane() == plane)
			{
				LocalPoint lp = LocalPoint.fromWorld(wv, tile);
				if (lp != null)
				{
					highlight = Perspective.getCanvasTilePoly(client, lp);
					end = toCanvas(wv, lp);
				}
			}
		}

		if (started && end != null)
		{
			line.lineTo(end.getX(), end.getY());
		}

		if (started)
		{
			g.setColor(color);
			g.draw(line);
		}

		if (highlight != null && config.highlightDestination())
		{
			g.setColor(color);
			g.draw(highlight);
			g.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), Math.min(color.getAlpha(), 50)));
			g.fill(highlight);
		}
		return null;
	}

	private Point toCanvas(WorldView wv, WorldPoint wp)
	{
		LocalPoint lp = LocalPoint.fromWorld(wv, wp);
		return lp == null ? null : toCanvas(wv, lp);
	}

	private Point toCanvas(WorldView wv, LocalPoint lp)
	{
		return Perspective.localToCanvas(client, lp, wv.getPlane());
	}
}

