package com.librarypilot;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import lombok.Getter;
import net.runelite.api.coords.WorldPoint;

class Bookcase
{
	Bookcase(WorldPoint location)
	{
		this.location = location;
		this.index = new ArrayList<>();
	}

	@Getter
	private final WorldPoint location;

	@Getter
	private final List<Integer> index;

	@Getter
	private boolean isBookSet;

	/**
	 * Book in this bookcase as found by the player.
	 * Will be correct as long as isBookSet is true, unless the library has reset;
	 */
	@Getter
	private Book book;

	/**
	 * Books that can be in this slot. Will only be populated if library.state != SolvedState.NO_DATA
	 */
	@Getter
	private final Set<Book> possibleBooks = new HashSet<>();

	void clearBook()
	{
		book = null;
		isBookSet = false;
	}

	void setBook(Book book)
	{
		this.book = book;
		this.isBookSet = true;
	}
}

package com.librarypilot;

import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Outlines the Books of Arcane Knowledge in the inventory when it is full, so they can be read to make space.
 */
class LibraryPilotItemOverlay extends WidgetItemOverlay
{
	private final LibraryPilotPlugin plugin;
	private final LibraryPilotConfig config;
	private final ItemManager itemManager;

	@Inject
	LibraryPilotItemOverlay(LibraryPilotPlugin plugin, LibraryPilotConfig config, ItemManager itemManager)
	{
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (itemId != ItemID.ARCEUUS_LIBRARY_REWARD || !plugin.isClaimXp())
		{
			return;
		}
		Rectangle bounds = widgetItem.getCanvasBounds();
		BufferedImage outline = itemManager.getItemOutline(itemId, widgetItem.getQuantity(), config.pathColor());
		graphics.drawImage(outline, (int) bounds.getX(), (int) bounds.getY(), null);
	}
}

package com.librarypilot;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(LibraryPilotConfig.GROUP)
public interface LibraryPilotConfig extends Config
{
	String GROUP = "librarypilot";
	String LEARNED_TRANSPORTS = "learnedTransports";

	@Alpha
	@ConfigItem(
		keyName = "pathColor",
		name = "Path colour",
		description = "Colour of the line to the next destination",
		position = 0
	)
	default Color pathColor()
	{
		return new Color(0, 255, 255, 220);
	}

	@Range(min = 1, max = 8)
	@ConfigItem(
		keyName = "lineWidth",
		name = "Line width",
		description = "Width of the path line",
		position = 1
	)
	default int lineWidth()
	{
		return 3;
	}

	@ConfigItem(
		keyName = "highlightDestination",
		name = "Highlight destination",
		description = "Outline the bookshelf, customer, staircase or railing the line leads to",
		position = 2
	)
	default boolean highlightDestination()
	{
		return true;
	}

	@ConfigItem(
		keyName = "useShortcuts",
		name = "Use railing shortcuts",
		description = "Route over the railings around the central hole (52/62 Agility) when that is faster than the stairs",
		position = 3
	)
	default boolean useShortcuts()
	{
		return true;
	}

	@ConfigItem(
		keyName = "searchUnknown",
		name = "Path to unsearched shelves",
		description = "When the requested book's location isn't known yet, lead to the nearest shelf that could have it",
		position = 4
	)
	default boolean searchUnknown()
	{
		return true;
	}

	@ConfigItem(
		keyName = "includeSam",
		name = "Get requests from Sam",
		description = "Also go to Sam for new requests. Off by default: requests alternate between Villia and Professor Gracklebone,"
			+ " and Sam is only visited when he gave you the current request",
		position = 5
	)
	default boolean includeSam()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showInfoBox",
